from itertools import combinations_with_replacement


def narcissisticCountInBase(b, n):
    count = 0
    k = 1
    while b ** (k - 1) <= n:
        for combo in combinations_with_replacement(range(b), k):
            s = sum(d ** k for d in combo)
            if s == 0 or s > n:
                continue
            digits = []
            x = s
            while x:
                digits.append(x % b)
                x //= b
            if len(digits) == k and sorted(digits) == list(combo):
                count += 1
        k += 1
    return count
